(6190870, 914232, 120915, '<td valign="top">Crop the bottom.</td>', 'Crop the bottom.', '2010-10-13 15:42:46.000000', NULL, 1),
(6190873, 913988, 46913, '<td valign="top">I love the photo, but I can''t fight the feeling that the metaphor in the title is very, very loose / questionable as part of a "Bridge" contest. Don''t get me wrong - I love original concepts for these contests and am rating down a lot of great photos this time because of a lack of originality... It''s just that this could have fit just as well in the "below the knees" contest, with a title like "The sun at foot-level."</td>', 'I love the photo, but I can''t fight the feeling that the metaphor in the title is very, very loose / questionable as part of a "Bridge" contest. Don''t get me wrong - I love original concepts for these contests and am rating down a lot of great photos this time because of a lack of originality... It''s just that this could have fit just as well in the "below the knees" contest, with a title like "The sun at foot-level."', '2010-10-13 15:45:55.000000', NULL, 1),
